function mystery(p):
    n = length of p
    st = an empty stack
    count = an array of length n filled with 0s
    for i from 1 to n:
        while st is not empty and p[i] < top of st:
            pop from st
            count[i] = count[i] + 1
        push p[i] into st
    return count
